package org.millenaire.common.item;import net.minecraft.world.item.*;import net.minecraft.world.entity.player.Player;import org.millenaire.common.village.Building;import org.millenaire.common.entity.MillVillager;public class TradeGood {public InvItem item;public String name,requiredTag;public int minReputation;public boolean autoGenerate;public int sell=10,buy=3;public TradeGood(Item i){item=new InvItem(i);name=i.toString();}public String getName(){return name;}public int getCalculatedSellingPrice(Building b,Player p){return sell;}public int getCalculatedBuyingPrice(Building b,Player p){return buy;}public int getCalculatedSellingPrice(MillVillager v){return sell;}}